    p.init('queue1_dummy');
    for (const c of p.getCards('hej')) c.remove();
    p.wunature = undefined;
    p.storage = {};
  }
  const [source, owner] = game.players;
  game.me = game.players.find(p => p.node.handcards1 === ui.handcards1) || source;
  game.swapControl(owner);
  const first = game.createCard('sha', 'club', 7);
  const second = game.createCard('tao', 'heart', 3);
  owner.directgain([first, second]);
  owner.wunature = 'wood';
  owner.addSkill('_shengke');
  const attack = game.createCard('sha', 'spade', 9);
  attack.wunature = 'metal';
  source.directgain([attack]);
  const root = game.createEvent('queue1Probe', false);
  root.parent = null;
  root.setContent(function () { window.queue1Done = true; event.finish(); game.pause(); });
  _status.event = root;
  _status.currentPhase = source;
  window.queue1Done = false;
  window.queue1Cards = { first, second, attack };
  window.queue1Root = root;
  const use = source.useCard(attack, [owner], false);
  use.animate = false;
  game.resume();
  return JSON.stringify({ event: _status.event.name, step: _status.event.step, paused: _status.paused,
    targetHp: owner.hp, hand: owner.getCards('h').map(c => c.name), done: window.queue1Done });
})();

new Promise((resolve, reject) => {
  let ticks = 0;
  const tick = () => {
    if (_status.paused && _status.event.name === window.queue1Expected) return resolve(JSON.stringify({
      event: _status.event.name, controls: _status.event.controls, confirm: ui.confirm?.str,
      prompt: _status.event.prompt, forced: _status.event.forced,
      hand: game.me.getCards('h').map(c => ({ name: c.name, suit: c.suit, rank: c.number })),
    }));
    if (++ticks > 500) return reject(Error('choice timeout at ' + _status.event.name));
    setTimeout(tick, 20);
  };
  tick();
});

new Promise((resolve, reject) => {
  let ticks = 0;
  const tick = () => {
    if (window.queue1Done) return resolve(JSON.stringify({ done: true,
      players: game.players.map((p, seat) => ({ seat, hp: p.hp,
        hand: p.getCards('h').map(c => ({ name: c.name, suit: c.suit, rank: c.number, wunature: c.wunature || null })),
        equips: p.getCards('e').map(c => ({ name: c.name, suit: c.suit, rank: c.number, wunature: c.wunature || null })),
      })),
    }));
    if (++ticks > 500) return reject(Error('finish timeout at ' + _status.event.name));
    setTimeout(tick, 20);
  };
  tick();
});
